package synth

import kotlin.properties.Delegates

fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

class Counter7020 {
    var current: Int by Delegates.observable(13) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
sealed class Outcome7021 {
    data class Success(val payload: String) : Outcome7021()
    data object Failure : Outcome7021()
}

fun describe7021(outcome: Outcome7021): String = when (outcome) {
    is Outcome7021.Success -> outcome.payload
    Outcome7021.Failure -> "failed"
}
